public class ArrayDeduperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("dedupe({4,2,4,3,2,4})", "[4, 2, 3]",
                    java.util.Arrays.toString(ArrayDeduper.dedupe(new int[]{4, 2, 4, 3, 2, 4})));
            check("dedupe({1,2,3}) already distinct", "[1, 2, 3]",
                    java.util.Arrays.toString(ArrayDeduper.dedupe(new int[]{1, 2, 3})));
            check("dedupe({7,7,7,7}) all same", "[7]",
                    java.util.Arrays.toString(ArrayDeduper.dedupe(new int[]{7, 7, 7, 7})));
            check("dedupe({}) empty", "[]",
                    java.util.Arrays.toString(ArrayDeduper.dedupe(new int[]{})));
            check("dedupe({0, -1, 0, -1, 5}) zeros and negatives", "[0, -1, 5]",
                    java.util.Arrays.toString(ArrayDeduper.dedupe(new int[]{0, -1, 0, -1, 5})));
            check("dedupe({9,1,9,1,9,2}) order kept", "[9, 1, 2]",
                    java.util.Arrays.toString(ArrayDeduper.dedupe(new int[]{9, 1, 9, 1, 9, 2})));
            int[] original = {5, 5, 6};
            ArrayDeduper.dedupe(original);
            check("original array unchanged", "[5, 5, 6]",
                    java.util.Arrays.toString(original));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

