public class ArrayDeduper {

    public static int[] dedupe(int[] a) {
        int[] kept = new int[a.length];
        int count = 0;
        for (int value : a) {
            boolean seen = false;
            for (int i = 0; i < count; i++) {
                if (kept[i] == value) {
                    seen = true;
                    break;
                }
            }
            if (!seen) {
                kept[count++] = value;
            }
        }
        return java.util.Arrays.copyOf(kept, count);
    }
}
